import{_ as t,o,c as s,ae as n}from"./chunks/framework.Dn6zxbF8.js";const h=JSON.parse('{"title":"NodeJS source code directory structure","description":"","frontmatter":{"id":"0541531435","title":"NodeJS source code directory structure","state":"Approved","created":"2020-11-21T00:00:00.000Z","tags":["nodejs","directory"],"category":"JavaScript"},"headers":[],"relativePath":"adrs/0541531435/README.md","filePath":"adrs/0541531435/README.md"}'),a={name:"adrs/0541531435/README.md"};function i(r,e,c,l,d,p){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="nodejs-source-code-directory-structure" tabindex="-1">NodeJS source code directory structure <a class="header-anchor" href="#nodejs-source-code-directory-structure" aria-label="Permalink to &quot;NodeJS source code directory structure&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>There are no guidelines on where to put the source code for your NodeJS projects.</p><ul><li>Do I suppose to use <code>src</code>, <code>lib</code>, <code>dist</code> or <code>build</code> directories, or maybe put everything at the root of the project?</li></ul><p>Not having a clear guideline adds cognitive load, as well as add friction contributing to projects, and sometimes relying on a particular group of people that know the unspoken/undocumented rule.</p><p>In other completely valid cases, like putting everything at the root of the project, don&#39;t take into consideration caveats like having so many metadata such as <code>.gitignore</code>, <code>.prettierrc</code>, <code>.eslintrc</code>, <code>.markdownlint.json</code>, <code>tsconfig.json</code> files and many other files and directories.</p><p>Subjectively speaking, they add noise and hard to navigate or concentrate when put all your files at the root of the project.</p><p>Furthermore,</p><ul><li><p>Where do I suppose to put my test files? What are the differences between X and Y directories?</p></li><li><p>How to structure the project when I have multiple testing frameworks, or multiple documentation tools?</p></li></ul><p>This ADR is an attempt to follow the steps of other ecosystems like Elixir, Ruby or Rust came to a consensus about this topic.</p><h3 id="about-compilations" tabindex="-1">About compilations <a class="header-anchor" href="#about-compilations" aria-label="Permalink to &quot;About compilations&quot;">​</a></h3><p>We should tell what requires compilation in the project, which is extremely useful in library projects since you should be aware of such detail to consume the project. Or in cases that you would like to run the project in production.</p><p>Having a directory that reflects such information is crucial to mitigate mistakes in application deployments, or misuse of libraries.</p><h3 id="about-test-frameworks" tabindex="-1">About test frameworks <a class="header-anchor" href="#about-test-frameworks" aria-label="Permalink to &quot;About test frameworks&quot;">​</a></h3><p>Sometimes you may have multiple test frameworks for your project, most likely for <code>end-to-end</code>, <code>integration</code>, or <code>unit</code> tests, but not limited to those concepts. Therefore, people have tried to come up with <code>./tests/integration</code>, <code>./tests/unit</code>, <code>./tests/end-to-end</code>.</p><p>Although that may be a clean way to structure your tests, the problems arrive when you try to articulate the differences between those categories without getting into an in-depth conversation about X vs. Y and end up with unclear boundaries, relying too much on the programmer&#39;s experiences to articulate the most optimal definition or decision.</p><p>Additionally, if you try to migrate your project to another testing tool that falls into one of those possible categories, you will mingle tests that are run differently depending on the underline tool, and that may be really important in some cases.</p><h3 id="about-documentation" tabindex="-1">About documentation <a class="header-anchor" href="#about-documentation" aria-label="Permalink to &quot;About documentation&quot;">​</a></h3><p>Documentation tools are amazingly diverse in the ecosystem; such tools require different configurations and code structure, therefore mingle tools may cause incompatible situations, or confusing documentation source code.</p><p>Also, it is unclear today what should I do if I have multiple documentation websites (internal or public as an example), and how to manage them.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li><p>You <strong>MUST</strong> follow the following directory structures:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>├── bin</span></span>
<span class="line"><span>├── dist</span></span>
<span class="line"><span>├── docs</span></span>
<span class="line"><span>│   ├── storybook</span></span>
<span class="line"><span>│   └── website</span></span>
<span class="line"><span>│   └── website-next</span></span>
<span class="line"><span>│   └── [another website or tool]</span></span>
<span class="line"><span>├── examples</span></span>
<span class="line"><span>├── lib</span></span>
<span class="line"><span>├── src</span></span>
<span class="line"><span>└── tests</span></span>
<span class="line"><span>    ├── cypress</span></span>
<span class="line"><span>    └── jest</span></span>
<span class="line"><span>    └── puppeteer</span></span>
<span class="line"><span>    └── [another testing tool]</span></span></code></pre></div></li><li><p>In the <code>./tests</code> directory, you <strong>MUST</strong> use the tool&#39;s name to reflect the tool used to run the tests.</p></li><li><p>In the <code>./docs</code> directory, you <strong>MUST</strong> separate documentation based on the underline tool or context (for example, <strong>internal</strong> or <strong>public</strong>) unless you only have one documentation tool or context.</p></li><li><p>You <strong>MUST</strong> place <code>storybook</code> documentation under <code>./docs</code>.</p></li><li><p><code>./src</code> <strong>MUST</strong> required compilation step, and you <strong>MUST</strong> compile the source code into <code>./dist</code> directory.</p></li><li><p><code>./dist</code> <strong>MUST</strong> required to compile <code>./src</code> directory to generate the source code, or any other compilation step in required cases.</p></li></ul><h3 id="about-files-and-directories" tabindex="-1">About files and directories <a class="header-anchor" href="#about-files-and-directories" aria-label="Permalink to &quot;About files and directories&quot;">​</a></h3><ul><li><strong>./package.json:</strong> the NodeJS package configuration.</li><li><strong>./bin:</strong> contains executables files.</li><li><strong>./dist:</strong> contains compiled source code.</li><li><strong>./docs:</strong> contains the documentation of the project.</li><li><strong>./examples:</strong> contains examples of the project&#39;s usage, primarily used in library projects.</li><li><strong>./lib:</strong> source code that does not require compilation.</li><li><strong>./src:</strong> source code that requires some compilation.</li><li><strong>./tests:</strong> contains the tests files.</li></ul>`,24)])])}const m=t(a,[["render",i]]);export{h as __pageData,m as default};
